"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["48611"],{48693(e){e.exports=JSON.parse('{"id":"FIN-1148","slug":"safe-haven-asset","term":"Safe-Haven Asset","also_known_as":[],"difficulty":"Advanced","definition":"A safe-haven asset is an investment that is expected to hold or increase its value during periods of market turmoil or economic crisis, when riskier assets are falling.","explanation":["When investors become fearful, they often sell shares and other risky investments and move money into assets they consider safer. These are called safe havens.","Traditional safe-haven assets include government bonds from financially strong countries, such as US Treasuries and German government bonds, gold, and certain currencies, such as the US dollar, the Swiss franc and the Japanese yen.","For example, during a sudden stock market fall, prices of high-quality government bonds often rise as investors seek safety, partly offsetting losses in a portfolio that holds both.","Safe havens do not always behave as expected. Their performance can depend on the cause of the crisis. In 2022, for example, rising inflation and interest rates caused both shares and government bonds to fall together. Gold can be volatile, and currencies can be affected by policy decisions. Holding a mix of assets that respond differently to different conditions is more reliable than relying on one safe haven."],"note":"","total":1500,"prev":{"slug":"runway","term":"Runway"},"next":{"slug":"safe","term":"SAFE (Simple Agreement for Future Equity)"}}')}}]);